package net.officefloor.hq.app.person;

import java.util.List;

/** A person on a sheet: the id the store assigned, their name and the grade (A, B or C) in force on
 *  the sheet's today, with every grade they have been given (oldest first), and the
 *  version of these values (up by one on each save), and their statements: how many have been taken,
 *  and the last one's due-total and date (both null before the first), and the date they are retired
 *  from (null when not retired; any date set means retired at once), and their holds (oldest first) and
 *  whether they have any (their open (OPEN or PENDING) claims dated within a hold, unless bound by a
 *  statement, then count in no live total), and their own terms in days (null when they have none), and their contact (null when they have none), and the sheet they were
 *  transferred from (null when they were not transferred here), and their past retirements (oldest first). */
public record Person(long id, String name, String grade, long version, long statementCount,
        String statedTotal, String statementDate, String retiredFrom, boolean held, List<GradeFrom> grades,
        List<Hold> holds, Integer terms, String contact, String origin,
        List<Retirement> retirements) {

    public Person withGrades(List<GradeFrom> grades) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements);
    }

    public Person withHolds(List<Hold> holds) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom,
                !holds.isEmpty(), grades, holds, terms, contact, origin, retirements);
    }

    public Person withRetirements(List<Retirement> retirements) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact, origin, retirements);
    }

    public boolean retired() {
        return retiredFrom != null;
    }

    /** Their holds as they act on live totals on the sheet's today: once their retirement date is reached
     *  (the sheet's today on or after it) they are held over every date as well. */
    public List<Hold> liveHolds(String today) {
        if (retiredFrom == null || today == null || retiredFrom.compareTo(today) > 0) return holds;
        List<Hold> all = new java.util.ArrayList<>(holds);
        all.add(new Hold(null, null));
        return all;
    }
}
package net.officefloor.hq.app.person;

/** The person form; {@code gradeFrom} is the date the grade is in force from (yyyy-mm-dd; blank for the
 *  sheet's today; an edit only), {@code terms} the person's own terms in days (blank for none), {@code contact} their contact (trimmed and lower-cased; blank for none), {@code version} the version the editor loaded (an edit only). */
public record PersonRequest(String name, String grade, Long version, String gradeFrom, String terms, String contact) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the person form: a name is required (trimmed; unique on the sheet, checked when saved), the grade
 *  must be A, B or C, and a from-date is yyyy-mm-dd (blank for the sheet's today), and the terms
 *  a whole number of days from 0 to 3650 (blank for none), and the contact is trimmed and
 *  lower-cased (blank for none; unique on the sheet, checked when saved). */
public class ValidatePerson {
    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> person) throws BadRequestException {
        person.set(NewPerson.check(request));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.dao.DuplicateKeyException;

/** Adding a person as the person form does: shared by the form and the people import. */
public final class NewPerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");
    private static final Pattern TERMS = Pattern.compile("\\d{1,4}");

    private NewPerson() {
    }

    /** The form's rules: the request trimmed and normalised, or refused. */
    public static PersonRequest check(PersonRequest request) throws BadRequestException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (name.isEmpty()) {
            throw new BadRequestException("name is required");
        }
        if (!GRADES.contains(grade)) {
            throw new BadRequestException("grade must be A, B or C");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                from = LocalDate.parse(from).toString();
            } catch (DateTimeParseException e) {
                throw new BadRequestException("from-date must be yyyy-mm-dd");
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && (!TERMS.matcher(terms).matches() || Integer.parseInt(terms) > 3650)) {
            throw new BadRequestException("terms must be a whole number of days from 0 to 3650");
        }
        String contact = request.contact() == null ? "" : request.contact().trim().toLowerCase(java.util.Locale.ROOT);
        return new PersonRequest(name, grade, request.version(), from,
                terms.isEmpty() ? "" : String.valueOf(Integer.parseInt(terms)), contact);
    }

    /** Refuse a validated person whose name or contact is already in use on the sheet. */
    public static void checkFree(PersonRepository repository, String id, PersonRequest request) throws BadRequestException {
        if (repository.nameTaken(id, request.name(), 0)) {
            throw new BadRequestException("name is already in use");
        }
        if (!request.contact().isEmpty() && repository.contactTaken(id, request.contact(), 0)) {
            throw new BadRequestException("contact is already in use");
        }
    }

    /** Add a validated, checked person, writing PERSON_ADDED and the rollup. */
    public static Person add(PersonRepository repository, Audit audit, Rollup rollup, String id, String by,
            PersonRequest request) throws BadRequestException {
        String contact = request.contact().isEmpty() ? null : request.contact();
        Rollup.Snapshot before = rollup.take(id);
        Person added;
        try {
            added = repository.add(id, request.name(), request.grade(),
                    request.terms().isEmpty() ? null : Integer.valueOf(request.terms()), contact);
        } catch (DuplicateKeyException e) {
            throw new BadRequestException("name is already in use");
        }
        audit.record("PERSON_ADDED sheet=" + id + " by=" + by + " name=" + added.name()
                + " grade=" + added.grade() + (added.terms() == null ? "" : " terms=" + added.terms())
                + (added.contact() == null ? "" : " contact=" + added.contact()));
        rollup.record(id, by, before);
        return added;
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.ConflictException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.web.bind.annotation.PathVariable;

/** Save an edited person; refused (409) when someone else has saved them since the editor loaded its version.
 *  The form's grade is recorded from its from-date (blank: the sheet's today), keeping their other grades,
 *  except that a save leaving the grade in force on the sheet's today as it is, with the from-date blank,
 *  records no grade. PERSON_EDITED carries the grade in force on the sheet's today after the save, then
 *  the person's own terms when the save changed them (empty when it cleared them), then their contact when
 *  the save changed it (empty when it cleared it). */
public class SavePerson {
    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @Val PersonRequest request, ServerHttpConnection connection, PersonRepository repository,
            SheetRepository sheets, Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException, ConflictException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
